            'bool', 'boolean', 'mixed', 'void',
        ];
        if (in_array($class, $primitives, true)) {
            /* A raw body is parsed as JSON text; a container element is already
             * a decoded value and is never parsed again (a string element such
             * as "true" or "5" is a string, not a bool or an int). Either way
             * the value must then already have the declared JSON type: a wrong
             * type is rejected rather than coerced ("abc" to 0, 1.9 to 1,
             * true to 1, "5" to 5). For int-typed raw bodies
             * JSON_BIGINT_AS_STRING preserves a value above PHP_INT_MAX as a
             * digit string, so the str to int to str round-trip equality below
             * is a bcmath-free overflow check. */
            $bigIntText = false;
            if (!$decoded && is_string($data)) {
                $bigIntText = ($class === 'int' || $class === 'integer')
                    && preg_match('/^\s*-?\d+\s*$/', $data) === 1;
                $data = json_decode(
                    $data,
                    true,
                    self::JSON_DECODE_DEPTH,
                    JSON_THROW_ON_ERROR | JSON_BIGINT_AS_STRING
                );
                if ($data === null) {
                    return null;
                }
            }
            if ($class === 'mixed' || $class === 'void') {
                return $data;
            }
            if ($class === 'int' || $class === 'integer') {
                if ($bigIntText && is_string($data)) {
                    $casted = (int) $data;
                    if ((string) $casted !== $data) {
                        throw new \OverflowException(
                            "Value '$data' overflows PHP int range "
                            . '(PHP_INT_MIN..PHP_INT_MAX)'
                        );
                    }
                    return $casted;
                }
                if (is_int($data)) {
                    return $data;
                }
            } elseif ($class === 'float' || $class === 'number') {
                if (is_int($data) || is_float($data)) {
                    return (float) $data;
                }
            } elseif ($class === 'bool' || $class === 'boolean') {
                if (is_bool($data)) {
                    return $data;
                }
            } elseif (is_string($data)) {
                return $data;
            }
            throw new \InvalidArgumentException(
                sprintf("Expected a JSON value of type '%s' but got %s", $class, get_debug_type($data))
            );
        }

        if ($class === 'object') {
            $data = $decoded ? $data : self::decodeJson($data);
            return (array) $data;
        }

        if ($class === 'DateTime') {
            if (!$decoded && is_string($data)) {
                $literal = json_decode($data, true, self::JSON_DECODE_DEPTH);
                if (is_string($literal)) {
                    $data = $literal;
                }
            }
            if (is_string($data) && $data !== '') {
                return self::parseRfc3339($data);
            }
            return null;
        }

        if ($class === 'DateTimeImmutable') {
            /* 4.8: OAS `format: time` (RFC 3339 partial-time, e.g.
             * "14:30:00") maps to \DateTimeImmutable. PHP has no
             * dedicated time-of-day type; \DateTimeImmutable parses the
             * wire string with today's date implied and callers project
             * the time portion via format('H:i:s'). */
            if (!$decoded && is_string($data)) {
                $literal = json_decode($data, true, self::JSON_DECODE_DEPTH);
                if (is_string($literal)) {
                    $data = $literal;
                }
            }
            if (is_string($data) && $data !== '') {
                try {
                    return new \DateTimeImmutable($data);
                } catch (\Exception) {
                    $cleaned = preg_replace('/(:\d{2}.\d{6})\d*/', '$1', $data);
                    return new \DateTimeImmutable((string) $cleaned);
                }
            }
            return null;
        }

        if ($class === 'DateInterval') {
            /* 4.8: OAS `format: duration` is a protobuf-JSON duration
             * string (e.g. "3600s" / "3600.000000001s" / "-1.5s"). The
             * ISO-8601 form \DateInterval's constructor parses is NOT the
             * wire form here, so we parse the protobuf-JSON shape and build
             * a round-tripping interval. Invalid strings surface as the
             * SerializationException used elsewhere for bad input. */
            if (!$decoded && is_string($data)) {
                $literal = json_decode($data, true, self::JSON_DECODE_DEPTH);
                if (is_string($literal)) {
                    $data = $literal;
                }
            }
            if (is_string($data) && $data !== '') {
                return self::parseProtobufDuration($data);
            }
            return null;
        }

        if ($class === \Symfony\Component\Uid\Uuid::class) {
            if (!$decoded && is_string($data)) {
                $literal = json_decode($data, true, self::JSON_DECODE_DEPTH);
                if (is_string($literal)) {
                    $data = $literal;
                }
            }
            if (is_string($data) && $data !== '') {
                return \Symfony\Component\Uid\Uuid::fromString($data);
            }
            return null;
        }

        if ($class === 'SplFileObject') {
            assert(is_string($data) || is_resource($data));

            $tempDir = sys_get_temp_dir();

            $pattern = '/inline; filename=[\'"]?([^\'"\s]+)[\'"]?$/i';
            if (
                is_array($httpHeaders)
                && array_key_exists('Content-Disposition', $httpHeaders)
                && preg_match($pattern, $httpHeaders['Content-Disposition'], $match)
            ) {
                $sanitizedFilename = $match[1];
                $pathPattern = "/.*[\/\\\\](.*)$/";
                if (preg_match($pathPattern, $sanitizedFilename, $pathMatch)) {
                    $sanitizedFilename = $pathMatch[1];
                }
                $filename = $tempDir . DIRECTORY_SEPARATOR . $sanitizedFilename;
            } else {
                $filename = tempnam($tempDir, '');
                if ($filename === false) {
                    throw new \RuntimeException('Failed to create temporary file');
                }
            }

            if (is_resource($data)) {
                $dest = fopen($filename, 'w');
                if ($dest === false) {
                    throw new \RuntimeException("Failed to open file: $filename");
                }
                stream_copy_to_stream($data, $dest);
                fclose($dest);
            } else {
                file_put_contents($filename, $data);
            }

            return new \SplFileObject($filename, 'r');
        }

        if (enum_exists($class)) {
            $data = $decoded ? $data : self::decodeJson($data);
            /** @var object $result */
            $result = self::getSerializer()->denormalize($data, $class);
            return $result;
        }

        /* Gap AU-residual: a oneOf/anyOf composed model carries a static
         * build() + a getActualInstance() accessor instead of
         * SerializedName-decorated typed properties. Routing it through the
         * generic Symfony denormalize() below would silently wrap the raw
         * decoded array in an empty union container — including a payload
         * that is missing the discriminator property. build() owns the
         * discriminator routing and THROWS on a missing / unknown / non-string
         * discriminator value (matching the other 10 SDKs); dispatch composed
         * classes through it so the contract violation surfaces loudly instead
         * of producing an un-typeable wrapper. The native
         * \InvalidArgumentException build() raises is wrapped in
         * SerializationException by the public deserialize() entry point. */
        if (
            class_exists($class)
            && method_exists($class, 'build')
            && method_exists($class, 'getActualInstance')
        ) {
            $payload = !$decoded && is_string($data)
                ? json_decode($data, true, self::JSON_DECODE_DEPTH)
                : $data;
            /** @var object $built */
            $built = $class::build($payload);
            return $built;
        }

        /* Only a raw body is JSON text. A container element is already a decoded
         * value, so a string element is never parsed again into an object. */
        if (!$decoded && is_string($data)) {
            try {
                $payload = json_decode($data, true, self::JSON_DECODE_DEPTH, JSON_THROW_ON_ERROR);
                /* A bare JSON `null` body decodes to a null return, matching the
                 * absent/null body the other 10 SDKs return null for, rather
                 * than throwing "Expected a JSON object, got null". */
                if ($payload === null) {
                    return null;
                }
                if (!is_array($payload)) {
                    throw new \InvalidArgumentException(
                        sprintf('Expected a JSON object, got %s', get_debug_type($payload))
                    );
                }
                self::assertRequiredPresent($payload, $class);
                self::assertPrimitiveTypes($payload, $class);
                self::assertNoUnknownProperties($payload, $class);
                self::assertBase64Fields($payload, $class);
                /* Canonical #4: pass the JSON format so Symfony widens an
                 * integral JSON value to a `float` property (e.g. {"lat":5}
                 * into a `?float $lat`). validateAndDenormalize only applies
                 * the int->float widening when the format string contains
                 * "json"; called without a format it raises
                 * NotNormalizableValueException for the integral value. The
                 * body always arrives as decoded JSON here, so naming the
                 * format is correct and matches the int-from-double widening
                 * the other SDKs perform. */
                /** @var object $result */
                $result = self::getSerializer()->denormalize($payload, $class, JsonEncoder::FORMAT);
                return self::captureAdditionalProperties($result, $payload);
            } catch (\Throwable $e) {
                throw new SerializationException($e->getMessage(), 0, $e);
            }
        }

        try {
            if ($decoded && !is_array($data)) {
                throw new \InvalidArgumentException(
                    sprintf('Expected a JSON object, got %s', get_debug_type($data))
                );
            }
            if (is_array($data)) {
                self::assertRequiredPresent($data, $class);
                self::assertPrimitiveTypes($data, $class);
                self::assertNoUnknownProperties($data, $class);
                self::assertBase64Fields($data, $class);
            }
            /* Pass the JSON format so Symfony widens an integral JSON value
             * to a `float` property (Canonical #4); see the string-data
             * branch above for the full rationale. */
            /** @var object $result */
            $result = self::getSerializer()->denormalize($data, $class, JsonEncoder::FORMAT);
            if (is_array($data)) {
                $result = self::captureAdditionalProperties($result, $data);
            }
            return $result;
        } catch (\Throwable $e) {
            throw new SerializationException($e->getMessage(), 0, $e);
        }
    }

    /**
     * Decode a raw JSON text body. Anything that is not a string (an already
     * decoded value) is returned unchanged, and unparseable text decodes to
     * null, which the callers reject with their own typed error.
     */
    private static function decodeJson(mixed $data): mixed
    {
        return is_string($data) ? json_decode($data, true, self::JSON_DECODE_DEPTH) : $data;
    }

    /**
     * F-BM-05 — hard-fail on a missing required property at deserialize.
     *
     * The generated model constructor declares every required var as a
     * non-defaulted parameter, so a payload that omits one is a contract
     * violation. Symfony's denormalizer is lenient for required-but-nullable
     * types (it silently passes null), so we walk the constructor parameters
     * that have no default value, map each to its wire name via the matching
     * property's SerializedName attribute, and throw an SDK-typed
     * InvalidArgumentException when the key is absent — aligning PHP with the
     * other 11 SDKs which all reject a missing required field.
     *
     * @param array<array-key, mixed> $data
     */
    private static function assertRequiredPresent(array $data, string $class): void
    {
        if (!class_exists($class)) {
            return;
        }
        $reflection = new \ReflectionClass($class);
        $constructor = $reflection->getConstructor();
        if (!$constructor instanceof \ReflectionMethod) {
            return;
        }
        foreach ($constructor->getParameters() as $param) {
            if ($param->isOptional() || $param->isDefaultValueAvailable()) {
                continue;
            }
            $wireName = $param->getName();
            if ($reflection->hasProperty($param->getName())) {
                $property = $reflection->getProperty($param->getName());
                foreach (
                    $property->getAttributes(
                        \Symfony\Component\Serializer\Attribute\SerializedName::class
                    ) as $attr
                ) {
                    $args = $attr->getArguments();
                    if (isset($args[0]) && is_string($args[0])) {
                        $wireName = $args[0];
                    } elseif (isset($args['name']) && is_string($args['name'])) {
                        $wireName = $args['name'];
                    }
                }
            }
            if (!array_key_exists($wireName, $data)) {
                throw new \InvalidArgumentException(sprintf(
                    "Missing required property '%s' on %s",
                    $wireName,
                    $class
                ));
            }
            /* DIVERGENCE #10: reject an explicitly-NULL value for a required,
             * non-nullable field. array_key_exists is true for an explicit
             * `"name": null`, so the absent-key check above lets a null
             * through to a non-nullable constructor parameter, where Symfony's
             * denormalizer behaviour is version-dependent and not guaranteed
             * to throw. Inspect the parameter's declared type: when the value
             * is null and the type does NOT allow null, that is a contract
             * violation. Required-but-nullable parameters (type allows null)
             * are left untouched, so an explicit null stays valid for them. */
            $paramType = $param->getType();
            if (
                $data[$wireName] === null
                && $paramType !== null
                && !$paramType->allowsNull()
            ) {
                throw new \InvalidArgumentException(sprintf(
                    "Required property '%s' on %s must not be null",
                    $wireName,
                    $class
                ));
            }
        }
    }

    /**
     * Gap S — strict primitive type-check.
     *
     * Symfony's ObjectNormalizer is permissive: it silently coerces
     * {"id": "42"} into an int property and {"active": 1} into a bool
     * property. Walking the declared properties via Reflection and
     * asserting that incoming primitive types match the declared
     * PHP type makes wire-type bugs throw an InvalidArgumentException
     * instead of producing a corrupted typed object. Aligns PHP with
     * Java/Kotlin/C#/Go/Swift/Rust which throw on type mismatch.
     *
     * @param array<array-key, mixed> $data
     */
    private static function assertPrimitiveTypes(array $data, string $class): void
    {
        if (!class_exists($class)) {
            return;
        }
        /* class_exists guarantees ReflectionClass won't throw — no try/catch needed. */
        $reflection = new \ReflectionClass($class);
        foreach ($reflection->getProperties() as $property) {
            $type = $property->getType();
            if (!$type instanceof \ReflectionNamedType) {
                continue;
            }
            $typeName = $type->getName();
            $serializedName = $property->getName();
            foreach ($property->getAttributes(\Symfony\Component\Serializer\Attribute\SerializedName::class) as $attr) {
                $args = $attr->getArguments();
                if (isset($args[0]) && is_string($args[0])) {
                    $serializedName = $args[0];
                } elseif (isset($args['name']) && is_string($args['name'])) {
                    $serializedName = $args['name'];
                }
            }
            if (!array_key_exists($serializedName, $data)) {
                continue;
            }
            $value = $data[$serializedName];
            if ($value === null) {
                continue;
            }
            $valid = match ($typeName) {
                'int' => is_int($value),
                'float' => is_int($value) || is_float($value),
                'bool' => is_bool($value),
                'string' => is_string($value),
                'array' => is_array($value),
                default => true,
            };
            if (!$valid) {
                throw new \InvalidArgumentException(sprintf(
                    "Gap S: property '%s' on %s expects %s, got %s",
                    $serializedName,
                    $class,
                    $typeName,
                    get_debug_type($value)
                ));
            }
        }
    }

    /**
     * OAS 3.1 / JSON Schema 2020-12 `unevaluatedProperties: false` enforcement.
     *
     * The model template emits a static `assertNoUnknownProperties(array $data)`
     * helper on every schema that declares `unevaluatedProperties: false`; that
     * helper throws when the decoded payload carries a key not declared on the
     * schema. Symfony's denormalizer is permissive and silently drops extra
     * attributes, so the per-model helper has to run BEFORE denormalize() for
     * the contract to bite. This guard dispatches to the model's own helper
     * when present (and is a no-op for every other class), aligning PHP with
     * Python's `extra="forbid"` and Java's throwing `@JsonAnySetter`.
     *
     * @param array<array-key, mixed> $data
     */
    private static function assertNoUnknownProperties(array $data, string $class): void
    {
        if (!class_exists($class) || !method_exists($class, 'assertNoUnknownProperties')) {
            return;
        }
        /* Dispatch via Reflection rather than a dynamic `$class::method()` call:
         * the static method's presence was confirmed by method_exists, and
         * ReflectionMethod::invoke keeps the call statically analysable at
         * PHPStan level 9 (a string-typed class-string static call is not). The
         * model-side helper throws \InvalidArgumentException on an unknown key;
         * the surrounding deserialize() try/catch wraps it in
         * SerializationException. */
        new \ReflectionMethod($class, 'assertNoUnknownProperties')->invoke(null, $data);
    }

    /**
     * Whether a string is strict RFC 4648 base64: standard alphabet, a length
     * that is a multiple of four with `=` padding, no whitespace or newline
     * and no URL-safe `-` or `_`. Non-zero trailing pad bits are not checked.
     */
    public static function isStrictBase64(string $text): bool
    {
        return preg_match('~\A(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?\z~', $text) === 1;
    }

    /**
     * Reject a `format: byte` model field whose wire value is not strict
     * base64 (see isStrictBase64), so malformed text fails at decode time
     * rather than when the raw-bytes accessor is first called.
     *
     * php models bytes as a string-typed property, so a byte field is
     * recognised by the raw-bytes accessor the model template emits for
     * every `format: byte` field (scalar, list element or map value):
     * `get<Property>AsBytes()`. Each string element is checked; null is
     * left alone.
     *
     * @param array<array-key, mixed> $data
     */
    private static function assertBase64Fields(array $data, string $class): void
    {
        if (!class_exists($class)) {
            return;
        }
        $reflection = new \ReflectionClass($class);
        foreach ($reflection->getProperties() as $property) {
            $name = $property->getName();
            $accessor = 'get' . str_replace('_', '', ucwords($name, '_')) . 'AsBytes';
            if (!$reflection->hasMethod($accessor)) {
                continue;
            }
            $wireName = $name;
            foreach (
                $property->getAttributes(
                    \Symfony\Component\Serializer\Attribute\SerializedName::class
                ) as $attr
            ) {
                $args = $attr->getArguments();
                if (isset($args[0]) && is_string($args[0])) {
                    $wireName = $args[0];
                }
            }
            if (!array_key_exists($wireName, $data)) {
                continue;
            }
            $value = $data[$wireName];
            $elements = is_array($value) ? $value : [$value];
            foreach ($elements as $element) {
                if (is_string($element) && !self::isStrictBase64($element)) {
                    throw new \InvalidArgumentException(sprintf(
                        "Invalid base64 for format: byte property '%s' on %s",
                        $wireName,
                        $class
                    ));
                }
            }
        }
    }

    /**
     * OAS `additionalProperties` capture.
     *
     * The model template emits a public `?\Ds\Map $additionalProperties`
     * property on every schema that declares an open `additionalProperties`
     * map. Symfony's denormalizer maps only the declared/SerializedName-tagged
     * properties and drops every other decoded key, so without this step the
     * undeclared keys are lost (data loss) and `$additionalProperties` stays
     * null. This collects every decoded key that does NOT correspond to a
     * declared property (matched by its wire / SerializedName) into a
     * `\Ds\Map` and assigns it, mirroring Python's capture validator and
     * Java's `@JsonAnySetter`. Returns the object unchanged when it has no
     * `additionalProperties` property.
     *
     * @param array<array-key, mixed> $data
     */
    private static function captureAdditionalProperties(object $result, array $data): object
    {
        if (!property_exists($result, 'additionalProperties')) {
            return $result;
        }
        $reflection = new \ReflectionClass($result);
        /* Build the set of wire names that map to a declared property so they
         * are NOT swept into the additionalProperties bag. Each declared
         * property contributes its SerializedName (or, absent the attribute,
         * its PHP name). The synthetic `additionalProperties` property itself
         * is never a wire key. */
        $declaredWireNames = [];
        foreach ($reflection->getProperties() as $property) {
            if ($property->getName() === 'additionalProperties') {
                continue;
            }
            $wireName = $property->getName();
            foreach (
                $property->getAttributes(
                    \Symfony\Component\Serializer\Attribute\SerializedName::class
                ) as $attr
            ) {
                $args = $attr->getArguments();
                if (isset($args[0]) && is_string($args[0])) {
                    $wireName = $args[0];
                } elseif (isset($args['name']) && is_string($args['name'])) {
                    $wireName = $args['name'];
                }
            }
            $declaredWireNames[$wireName] = true;
        }

        /** @var array<string, mixed> $extra */
        $extra = [];
        foreach ($data as $key => $value) {
            if (!isset($declaredWireNames[(string) $key])) {
                $extra[(string) $key] = $value;
            }
        }
        if ($extra !== []) {
            /* The declared property type is `?\Ds\Map`; assign a populated map
             * so callers read undeclared keys back through the same container
             * type the model documents. */
            $result->additionalProperties = new \Ds\Map($extra);
        }
        return $result;
    }

    /**
     * Convert a value to a string suitable for use as a URL path parameter.
     */
    public static function toPathValue(mixed $value): string
    {
        return self::stringify($value);
    }

    /**
     * Formats a `format: date` value as YYYY-MM-DD for wire serialization.
     * PHP has only DateTime (no separate date-only type), so the codegen
     * checks the spec format and routes through this helper to strip the
     * time component. Without this, a date param goes out as a full ATOM
     * (ISO+offset) string, mismatching the 6 SDKs (Java/Kotlin/C#/Python/
     * Ruby/Elixir) with native LocalDate types.
     */
    public static function toPathDateValue(mixed $value): string
    {
        if ($value === null) {
            return '';
        }
        if ($value instanceof \DateTimeInterface) {
            return $value->format('Y-m-d');
        }
        if (is_string($value)) {
            return substr($value, 0, 10);
        }
        return self::stringify($value);
    }

    /**
     * Convert a value to a representation suitable for use as a query parameter.
     * For collections, joins using the specified collection format delimiter.
     *
     * @return mixed the query value
     */
    public static function toQueryValue(mixed $value, ?string $collectionFormat = null): mixed
    {
        if ($value === null) {
            return null;
        }

        if (is_array($value)) {
            $items = array_map(self::stringify(...), $value);
            return match ($collectionFormat) {
                'ssv' => implode(' ', $items),
                'tsv' => implode("\t", $items),
                'pipes' => implode('|', $items),
                'multi' => $items,
                default => implode(',', $items), // csv or default
            };
        }

        return self::stringify($value);
    }

    /**
     * Convert a value to a string suitable for use as an HTTP header value.
     */
    public static function toHeaderValue(mixed $value): string
    {
        if (is_array($value)) {
            return implode(',', array_map(self::stringify(...), $value));
        }

        return self::stringify($value);
    }

    /**
     * Convert a value to a string suitable for use as an HTTP cookie value.
     * Cookie values follow the same encoding rules as header values.
     *
     * @param mixed $value the value to convert
     *
     * @return string string representation
     */
    public static function toCookieValue(mixed $value): string
    {
        return self::toHeaderValue($value);
    }

    /**
     * Convert a value to a representation suitable for use as a form parameter.
     */
    public static function toFormValue(mixed $value): string
    {
        if ($value instanceof \SplFileObject) {
            return $value->getRealPath();
        }
        return self::stringify($value);
    }

    /**
     * Resolve a oneOf schema by trying each candidate deserializer in order.
     * Each candidate is a closure that accepts the raw data and returns a
     * deserialized value, or throws on failure.
     *
     * @param mixed               $data       the data to match
     * @param array<callable>     $candidates list of deserializer closures
     *
     * @return mixed the first successfully deserialized value
     *
     * @throws \UnexpectedValueException when the data matches none of the
     *         candidate schemas. Throws rather than returning null so that
     *         shape-mismatch bugs surface loudly — aligns with Python,
     *         Swift, Dart, Go, Rust (5 of 12 already throw).
     */
    public static function resolveOneOf(mixed $data, array $candidates): mixed
    {
        foreach ($candidates as $candidate) {
            try {
                return $candidate($data);
            } catch (\Throwable) {
                continue;
            }
        }
        throw new \UnexpectedValueException(
            'No oneOf/anyOf variant matched the JSON'
        );
    }

    /**
     * Resolve an anyOf schema by trying each candidate deserializer in order.
     * Delegates to {@see resolveOneOf}.
     *
     * @param mixed               $data       the data to match
     * @param array<callable>     $candidates list of deserializer closures
     *
     * @return mixed the first successfully deserialized value
     *
     * @throws \UnexpectedValueException when the data matches none of the
     *         candidate schemas
     */
    public static function resolveAnyOf(mixed $data, array $candidates): mixed
    {
        return self::resolveOneOf($data, $candidates);
    }

    /**
     * Resolve an anyOf schema by collecting EVERY candidate that successfully
     * deserializes, not just the first. The OAS `anyOf` keyword matches when
     * the data satisfies one OR MORE of the listed schemas, so a payload that
     * co-satisfies several variants must retain all of them — returning only
     * the first would silently drop the other variants' fields and break a
     * lossless round-trip. Each retained variant is held independently; the
     * union of their fields is re-emitted on serialize via
     * {@see sanitizeForSerialization} (which merges the field-set of every
     * variant exposed through getActualInstances()).
     *
     * @param mixed           $data       the data to match
     * @param array<callable> $candidates list of deserializer closures
     *
     * @return array<int, mixed> every successfully deserialized variant, in
     *         declaration order
     *
     * @throws \UnexpectedValueException when the data matches no candidate
     *         schema. Throws rather than returning an empty list so a
     *         shape-mismatch surfaces loudly, mirroring {@see resolveOneOf}.
     */
    public static function resolveAnyOfAll(mixed $data, array $candidates): array
    {
        $matched = [];
        foreach ($candidates as $candidate) {
            try {
                $matched[] = $candidate($data);
            } catch (\Throwable) {
                continue;
            }
        }
        if ($matched === []) {
            throw new \UnexpectedValueException(
                'No oneOf/anyOf variant matched the JSON'
            );
        }
        return $matched;
    }

    /**
     * Qualify an unqualified model class name with the model namespace.
     * Primitive types (string, int, etc.) and already-qualified names are returned as-is.
     */
    public static function qualifySchemaName(string $schema): string
    {
        if (str_contains($schema, '\\') || !preg_match('/^[A-Z]/', $schema)) {
            return $schema;
        }
        $fqcn = 'PetstoreClient\Models\\' . $schema;
        return class_exists($fqcn) ? $fqcn : $schema;
    }

    /**
     * 2.1 — Decode an OAS `format: byte` field value to its raw binary string.
     * Returns null for null/empty input. Invalid base64 THROWS a
     * SerializationException (matching ruby/elixir), rather than silently
     * returning null, so a wire-shape violation surfaces to the caller.
     *
     * The wire form for `format: byte` is a base64-encoded string; SDK users
     * call this helper to recover the underlying bytes.
     */
    public static function decodeBytes(?string $encoded): ?string
    {
        if ($encoded === null || $encoded === '') {
            return null;
        }
        $decoded = self::isStrictBase64($encoded) ? base64_decode($encoded, true) : false;
        if ($decoded === false) {
            throw new SerializationException(
                "Invalid base64 for format: byte: " . $encoded
            );
        }
        return $decoded;
    }

    /**
     * 2.1 — Encode raw bytes as a base64 string suitable for an OAS
     * `format: byte` field. Returns null for null input.
     */
    public static function encodeBytes(?string $raw): ?string
    {
        if ($raw === null) {
            return null;
        }
        return base64_encode($raw);
    }

    /**
     * Resolve the scalar `format: byte` branch of a oneOf/anyOf union.
     *
     * The wire form for `format: byte` is a base64 STRING. This candidate is
     * invoked by {@see resolveOneOf} with already-decoded PHP data (the
     * composed model's build() json_decodes the body before dispatching), so
     * it receives a PHP string for the scalar branch and returns it unchanged
     * as the union's actual instance — the same wire-form-in-place convention
     * the bare scalar byte field uses, so serializing the union re-emits the
     * base64 string verbatim. A non-string payload (e.g. a decoded JSON array)
     * throws so {@see resolveOneOf} falls through to the next declared branch;
     * this is what keeps a scalar base64 string from being mis-parsed as the
     * array variant when both byte branches exist.
     */
    public static function decodeByteOneOfScalar(mixed $data): string
    {
        if (!is_string($data)) {
            throw new \InvalidArgumentException(
                'Expected a base64 string for the scalar byte variant but got '
                . get_debug_type($data)
            );
        }
        return $data;
    }

    /**
     * Resolve the array `format: byte` branch of a oneOf/anyOf union.
     *
     * Each element travels on the wire as a base64 STRING. This candidate is
     * invoked by {@see resolveOneOf} with already-decoded PHP data, so it
     * receives a PHP array of strings for the array branch, validates every
     * element is a string, and returns a {@see \Ds\Vector} holding the base64
     * strings unchanged — serializing the union re-emits the array of base64
     * strings verbatim. A non-array payload, or one with a non-string element,
     * throws so {@see resolveOneOf} falls through to the next branch.
     *
     * @return \Ds\Vector<string>
     */
    public static function decodeByteOneOfArray(mixed $data): \Ds\Vector
    {
        if (!is_array($data)) {
            throw new \InvalidArgumentException(
                'Expected an array of base64 strings for the array byte variant'
                . ' but got ' . get_debug_type($data)
            );
        }
        $items = [];
        foreach ($data as $element) {
            if (!is_string($element)) {
                throw new \InvalidArgumentException(
                    'Expected every array byte element to be a base64 string but got '
                    . get_debug_type($element)
                );
            }
            $items[] = $element;
        }
        return new \Ds\Vector($items);
    }

    /**
     * 4.8: format a \DateInterval as a protobuf-JSON duration string.
     *
     * google.protobuf.Duration is encoded as the number of seconds followed
     * by an "s" suffix (e.g. "3600s"); fractional seconds are written as a
     * decimal with 3, 6, or 9 digits — the smallest precision that preserves
     * the value (e.g. "3600.000000001s"). google.protobuf.Duration has no
     * month/year components, so the interval's ->y/->m are ignored (protobuf
     * durations never set them); days are folded into seconds. A negative
     * interval (->invert === 1) is prefixed with "-".
     */
    public static function formatProtobufDuration(\DateInterval $interval): string
    {
        $sign = $interval->invert === 1 ? '-' : '';

        $seconds = ((($interval->d * 24 + $interval->h) * 60) + $interval->i) * 60
            + $interval->s;
        /* ->f is fractional seconds in the range [0, 1); scale to nanos and
         * round to the nearest whole nanosecond. */
        $nanos = (int) round($interval->f * 1_000_000_000);
        if ($nanos >= 1_000_000_000) {
            $seconds += intdiv($nanos, 1_000_000_000);
            $nanos %= 1_000_000_000;
        }

        if ($nanos === 0) {
            return $sign . $seconds . 's';
        }

        /* Zero-pad to 9 digits, then trim trailing zeros down to the nearest
         * 3/6/9-digit boundary so the fraction stays a valid protobuf-JSON
         * sub-second value. */
        $frac = str_pad((string) $nanos, 9, '0', STR_PAD_LEFT);
        if (str_ends_with($frac, '000000')) {
            $frac = substr($frac, 0, 3);
        } elseif (str_ends_with($frac, '000')) {
            $frac = substr($frac, 0, 6);
        }

        return $sign . $seconds . '.' . $frac . 's';
    }

    /**
     * 4.8: parse a protobuf-JSON duration string into a \DateInterval.
     *
     * Accepts the wire form "[-]<seconds>[.<frac>]s" (e.g. "3600s",
     * "3600.000000001s", "-1.5s"). The whole-seconds part becomes the
     * interval's seconds; the fractional part is right-padded to 9 digits and
     * stored as ->f so the value round-trips through formatProtobufDuration.
     * A leading "-" sets ->invert. Any other shape throws the SDK-owned
     * SerializationException used elsewhere for malformed input.
     *
     * Returns a {@see PreciseDuration} (a \DateInterval subclass) rather than a
     * stock \DateInterval: native ->f truncates sub-microsecond fractions to
     * 0.0, which would silently drop nanosecond durations on parse.
     */
    public static function parseProtobufDuration(string $value): \DateInterval
    {
        if (preg_match('/^(-?)(\d+)(?:\.(\d{1,9}))?s$/', $value, $m) !== 1) {
            throw new SerializationException(
                "Invalid protobuf-JSON duration '$value': "
                . 'expected "<seconds>[.<fraction>]s"'
            );
        }

        /* PHP's \DateInterval::$f stores at most microsecond precision: any
         * value below 1e-6 assigned to it is truncated to 0.0, so a plain
         * \DateInterval cannot round-trip the nanosecond fractions that
         * google.protobuf.Duration allows (e.g. "3600.000000001s"). Build a
         * PreciseDuration instead — a \DateInterval subclass that bypasses the
         * lossy native initialiser and keeps ->f as a full-precision float. */
        $interval = new PreciseDuration();
        $interval->s = (int) $m[2];

        if (isset($m[3])) {
            /* Right-pad the captured fraction to 9 digits (nanoseconds) so the
             * scale is fixed regardless of how many digits were written: ".1"
             * -> "100000000" ns -> 0.1s, ".000000001" -> "000000001" -> 1 ns
             * -> 1.0e-9 s. \d{1,9} guarantees a non-empty capture. */
            $interval->f = (int) str_pad($m[3], 9, '0', STR_PAD_RIGHT) / 1_000_000_000;
        }

        if ($m[1] === '-') {
            $interval->invert = 1;
        }

        return $interval;
    }
}
